export function CommissionPreview({
  price,
  tip,
  rule,
  showExampleLabel = true,
  className,
}: CommissionPreviewProps) {
  const { commission, tipCommission, total, breakdown } = calculateCommission(price, tip, rule)
  const isValid = rule.percentage != null || rule.flat_fee_cents != null

  if (!isValid) {
    return (
      <div className={cn('commission-preview opacity-50', className)}>
        <p className="commission-preview-label">Preview</p>
        <p className="text-xs text-muted-foreground mt-1">
          Enter a commission structure above to see a preview.
        </p>
      </div>
    )
  }

  return (
    <div className={cn('commission-preview', className)}>
      {showExampleLabel && (
        <p className="commission-preview-label mb-2">
          Preview · example: {formatCurrency(price)} booking + {formatCurrency(tip)} tip
        </p>
      )}
      <div className="space-y-1.5">
        <div className="flex items-center justify-between">
          <span className="text-xs text-muted-foreground">{breakdown}</span>
          <span className="commission-preview-value tabular-nums">{formatCurrency(commission)}</span>
        </div>
        {tip > 0 && tipCommission > 0 && (
          <div className="flex items-center justify-between">
