interface TimelineStep {
  key: PayrollRunStatus
  label: string
  ts?: string | null
}

const ORDERED_STEPS: TimelineStep[] = PAYROLL_STEPS.map((s) => ({ key: s.key as PayrollRunStatus, label: s.label }))

type StepState = 'completed' | 'current' | 'pending'

function getStepState(stepKey: PayrollRunStatus, currentStatus: PayrollRunStatus): StepState {
  const order: PayrollRunStatus[] = ['draft', 'calculated', 'approved', 'paid']
  const stepIdx = order.indexOf(stepKey)
  const currentIdx = order.indexOf(currentStatus)

  if (currentStatus === 'cancelled') {
    // Show all steps as completed up to where it was cancelled
    return stepIdx < currentIdx ? 'completed' : 'pending'
  }

  if (stepIdx < currentIdx) return 'completed'
  if (stepIdx === currentIdx) return 'current'
  return 'pending'
