/**
 * GET  /api/schedule/templates         — list saved schedule templates for the studio
 * POST /api/schedule/templates         — save a new template from current week slots
 */
import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const CreateTemplateSchema = z.object({
  name: z.string().min(1).max(100),
  slots: z.array(z.object({
    artist_id: z.string().uuid(),
    day_of_week: z.number().int().min(0).max(6),
    start_time: z.string().regex(/^\d{2}:\d{2}(:\d{2})?$/),
    end_time: z.string().regex(/^\d{2}:\d{2}(:\d{2})?$/),
  })),
})

export async function GET(_req: NextRequest) {
  const supabase = await createClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  const { data, error } = await supabase
    .from('schedule_templates')
    .select('id, name, is_system, created_at')
    .eq('studio_id', member.studio_id)
    .order('is_system', { ascending: false })
    .order('created_at', { ascending: false })

  if (error) {
    logger.error({ error, studioId: member.studio_id }, 'Failed to fetch schedule templates')
    return Response.json({ error: 'Failed to load templates' }, { status: 500 })
  }

  return Response.json({ data: data ?? [] })
}

export async function POST(req: NextRequest) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Rate limited' }, { status: 429 })

  const supabase = await createClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('role, studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  if (member.role !== 'owner' && member.role !== 'admin' && member.role !== 'manager') {
    return Response.json({ error: 'Forbidden — managers, owners, and admins can save templates' }, { status: 403 })
  }

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return Response.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = CreateTemplateSchema.safeParse(body)
  if (!parsed.success) {
    return Response.json({ error: parsed.error.flatten() }, { status: 422 })
  }

  const { data: template, error } = await supabase
    .from('schedule_templates')
    .insert({
      studio_id: member.studio_id,
      created_by: user.id,
      name: parsed.data.name,
      data: { slots: parsed.data.slots },
      is_system: false,
    })
    .select('id, name, is_system, created_at')
    .single()

  if (error) {
    logger.error({ error, studioId: member.studio_id }, 'Failed to save schedule template')
    return Response.json({ error: 'Failed to save template' }, { status: 500 })
  }

  return Response.json({ data: template }, { status: 201 })
}

import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const PatchAccessSchema = z.object({
  show_on_booking_page:  z.boolean().optional(),
  can_view_clients:      z.boolean().optional(),
  can_edit_bookings:     z.boolean().optional(),
  can_message_clients:   z.boolean().optional(),
})

export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const supabase = await createClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('role, studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  const { data: engagement, error } = await supabase
    .from('guest_artist_engagements')
    .select('show_on_booking_page, can_view_clients, can_edit_bookings, can_message_clients')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()

  if (error || !engagement) {
    logger.warn({ engagementId: id, error }, 'guest_artist_access GET: engagement not found')
    return Response.json({ error: 'Not found' }, { status: 404 })
  }

  return Response.json({
    data: {
      show_on_booking_page: engagement.show_on_booking_page,
      can_view_clients:     engagement.can_view_clients,
      can_edit_bookings:    engagement.can_edit_bookings,
      can_message_clients:  engagement.can_message_clients,
    },
  })
}

export async function PATCH(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params

  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Rate limited' }, { status: 429 })

  const supabase = await createClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('role, studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  if (member.role !== 'owner' && member.role !== 'admin') {
    return Response.json({ error: 'Forbidden — only owners and admins can change access' }, { status: 403 })
  }

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return Response.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = PatchAccessSchema.safeParse(body)
  if (!parsed.success) {
    return Response.json({ error: parsed.error.flatten() }, { status: 422 })
  }

  const patch = parsed.data
  type DbPatch = {
    show_on_booking_page?: boolean
    can_view_clients?: boolean
    can_edit_bookings?: boolean
    can_message_clients?: boolean
  }
  const dbPatch: DbPatch = {}
  if (patch.show_on_booking_page !== undefined) dbPatch.show_on_booking_page = patch.show_on_booking_page
  if (patch.can_view_clients     !== undefined) dbPatch.can_view_clients     = patch.can_view_clients
  if (patch.can_edit_bookings    !== undefined) dbPatch.can_edit_bookings    = patch.can_edit_bookings
  if (patch.can_message_clients  !== undefined) dbPatch.can_message_clients  = patch.can_message_clients

  if (Object.keys(dbPatch).length === 0) {
    const { data: current } = await supabase
      .from('guest_artist_engagements')
      .select('show_on_booking_page, can_view_clients, can_edit_bookings, can_message_clients')
      .eq('id', id)
      .eq('studio_id', member.studio_id)
      .single()

    return Response.json({
      data: {
        show_on_booking_page: current?.show_on_booking_page ?? false,
        can_view_clients:     current?.can_view_clients     ?? false,
        can_edit_bookings:    current?.can_edit_bookings    ?? false,
        can_message_clients:  current?.can_message_clients  ?? false,
      },
    })
  }

  const { data: updated, error } = await supabase
    .from('guest_artist_engagements')
    .update(dbPatch)
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .select('show_on_booking_page, can_view_clients, can_edit_bookings, can_message_clients')
    .single()

  if (error || !updated) {
    logger.error({ engagementId: id, error }, 'guest_artist_access PATCH: update failed')
    return Response.json({ error: 'Update failed' }, { status: 500 })
  }

  return Response.json({
    data: {
      show_on_booking_page: updated.show_on_booking_page,
      can_view_clients:     updated.can_view_clients,
      can_edit_bookings:    updated.can_edit_bookings,
      can_message_clients:  updated.can_message_clients,
    },
  })
}

