'use client'

import { cn } from '@/lib/utils'

export type PaymentStatus =
  | 'succeeded'
  | 'pending'
  | 'processing'
  | 'refunded'
  | 'partially_refunded'
  | 'disputed'
  | 'failed'

const STATUS_CONFIG: Record<
  PaymentStatus,
  { label: string; dotClass: string; pillClass: string }
> = {
  succeeded: {
    label: 'Succeeded',
    dotClass: 'bg-[var(--color-success)]',
    pillClass: 'bg-[var(--color-success-bg)] text-[var(--color-success-foreground)]',
  },
  pending: {
    label: 'Pending',
    dotClass: 'bg-[var(--color-warning)]',
    pillClass: 'bg-[var(--color-warning-bg)] text-[var(--color-warning-foreground)]',
  },
  processing: {
    label: 'Processing',
    dotClass: 'bg-[var(--color-warning)]',
    pillClass: 'bg-[var(--color-warning-bg)] text-[var(--color-warning-foreground)]',
  },
  refunded: {
    label: 'Refunded',
    dotClass: 'bg-muted-foreground',
    pillClass: 'bg-muted text-muted-foreground',
  },
  partially_refunded: {
    label: 'Partial refund',
    dotClass: 'bg-[var(--color-warning)]',
    pillClass: 'bg-[var(--color-warning-bg)] text-[var(--color-warning-foreground)]',
  },
  disputed: {
    label: 'Disputed',
    dotClass: 'bg-destructive',
    pillClass: 'bg-destructive/10 text-destructive',
  },
  failed: {
    label: 'Failed',
    dotClass: 'bg-destructive',
    pillClass: 'bg-destructive/10 text-destructive',
  },
}

interface PaymentStatusBadgeProps {
  status: PaymentStatus
  className?: string
}

export function PaymentStatusBadge({ status, className }: PaymentStatusBadgeProps) {
  const config = STATUS_CONFIG[status] ?? STATUS_CONFIG.pending

  return (
    <span
      className={cn(
        'inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-semibold',
        config.pillClass,
        className,
      )}
    >
      <span className={cn('h-1.5 w-1.5 rounded-full shrink-0', config.dotClass)} />
      {config.label}
    </span>
  )
}

'use client'

import { useState } from 'react'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import { Input } from '@/components/ui/input'
import { Separator } from '@/components/ui/separator'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Label } from '@/components/ui/label'
import type { PaymentStatus } from './PaymentStatusBadge'

export interface PaymentsFilters {
  statuses: PaymentStatus[]
  methods: string[]
  minAmount: string
  maxAmount: string
  dateFrom: string
  dateTo: string
  artistId: string
  clientSearch: string
}

interface PaymentsFilterSheetProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  filters: PaymentsFilters
  onApply: (filters: PaymentsFilters) => void
  artists?: { id: string; name: string }[]
}

const STATUS_OPTIONS: { value: PaymentStatus; label: string }[] = [
  { value: 'succeeded', label: 'Succeeded' },
  { value: 'pending',   label: 'Pending' },
  { value: 'refunded',  label: 'Refunded' },
  { value: 'partially_refunded', label: 'Partially refunded' },
  { value: 'disputed',  label: 'Disputed' },
  { value: 'failed',    label: 'Failed' },
]

const METHOD_OPTIONS = [
  { value: 'card',    label: 'Card' },
  { value: 'cash',    label: 'Cash' },
  { value: 'zelle',   label: 'Zelle' },
  { value: 'cashapp', label: 'Cash App' },
  { value: 'other',   label: 'Other' },
]

const DATE_PRESETS = [
  { label: 'Today',        from: () => today(),     to: () => today() },
  { label: 'This week',    from: () => thisWeekStart(), to: () => today() },
  { label: 'This month',   from: () => thisMonthStart(), to: () => today() },
  { label: 'Last month',   from: () => lastMonthStart(), to: () => lastMonthEnd() },
  { label: 'Last 90 days', from: () => daysAgo(90), to: () => today() },
]

function today() {
  return new Date().toISOString().split('T')[0]!
}
function daysAgo(n: number) {
  const d = new Date()
  d.setDate(d.getDate() - n)
  return d.toISOString().split('T')[0]!
}
function thisWeekStart() {
  const d = new Date()
  d.setDate(d.getDate() - d.getDay())
  return d.toISOString().split('T')[0]!
}
function thisMonthStart() {
  const d = new Date()
  d.setDate(1)
  return d.toISOString().split('T')[0]!
}
function lastMonthStart() {
  const d = new Date()
  d.setDate(1)
  d.setMonth(d.getMonth() - 1)
  return d.toISOString().split('T')[0]!
}
function lastMonthEnd() {
  const d = new Date()
  d.setDate(0) // last day of previous month
  return d.toISOString().split('T')[0]!
}

export function PaymentsFilterSheet({
  open,
  onOpenChange,
  filters,
  onApply,
  artists = [],
}: PaymentsFilterSheetProps) {
  const [local, setLocal] = useState<PaymentsFilters>(filters)

  function toggleStatus(s: PaymentStatus) {
    setLocal(prev => ({
      ...prev,
      statuses: prev.statuses.includes(s)
        ? prev.statuses.filter(x => x !== s)
        : [...prev.statuses, s],
    }))
  }

  function toggleMethod(m: string) {
    setLocal(prev => ({
      ...prev,
      methods: prev.methods.includes(m)
        ? prev.methods.filter(x => x !== m)
        : [...prev.methods, m],
    }))
  }

  function applyPreset(preset: (typeof DATE_PRESETS)[number]) {
    setLocal(prev => ({
      ...prev,
      dateFrom: preset.from(),
      dateTo: preset.to(),
    }))
  }

  function clearAll() {
    const blank: PaymentsFilters = {
      statuses: [],
      methods: [],
      minAmount: '',
      maxAmount: '',
      dateFrom: '',
      dateTo: '',
      artistId: '',
      clientSearch: '',
    }
    setLocal(blank)
    onApply(blank)
    onOpenChange(false)
  }

  function handleApply() {
    onApply(local)
    onOpenChange(false)
  }

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="right"
        className="w-[400px] sm:w-[400px] flex flex-col gap-0 p-0"
