'use client'

import { useState, useMemo } from 'react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Checkbox } from '@/components/ui/checkbox'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { AlertTriangle, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { formatCurrency } from '@/lib/utils'
import { logAuditAction } from '@/lib/audit'

export interface PaymentRefundModalPayment {
  id: string
  amount_cents: number
  client_name: string
  client_id: string
  card_last4?: string | null
  booking_id?: string | null
  commission_amount_cents?: number
  currency?: string
}

interface PaymentRefundModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  payment: PaymentRefundModalPayment | null
  onSuccess?: (paymentId: string) => void
}

const SAFETY_GATE_THRESHOLD_CENTS = 50000 // $500

export function PaymentRefundModal({
  open,
  onOpenChange,
  payment,
  onSuccess,
}: PaymentRefundModalProps) {
  const [refundAmount, setRefundAmount] = useState('')
  const [reason, setReason] = useState('')
  const [note, setNote] = useState('')
  const [restock, setRestock] = useState(false)
  const [confirmName, setConfirmName] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)

  const amountCents = payment?.amount_cents ?? 0
  const refundCents = useMemo(() => {
    const parsed = parseFloat(refundAmount)
    if (isNaN(parsed) || parsed <= 0) return amountCents
    return Math.min(Math.round(parsed * 100), amountCents)
  }, [refundAmount, amountCents])

  const isFullRefund = refundCents === amountCents
  const needsSafetyGate = isFullRefund && amountCents > SAFETY_GATE_THRESHOLD_CENTS
  const canConfirm =
    reason.length > 0 &&
    (!needsSafetyGate || confirmName === (payment?.client_name ?? ''))

  function handleClose() {
    setRefundAmount('')
    setReason('')
    setNote('')
    setRestock(false)
    setConfirmName('')
    onOpenChange(false)
  }

  async function handleRefund() {
    if (!payment || !canConfirm) return
    setIsSubmitting(true)
    try {
      const res = await fetch(`/api/payments/${payment.id}/refund`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          amount_cents: refundCents,
          reason,
          note: note || undefined,
          restock_inventory: restock,
        }),
      })
      if (!res.ok) {
        const data = await res.json() as { error?: string }
        throw new Error(data.error ?? 'Refund failed')
      }
      toast.success(`Refund of ${formatCurrency(refundCents)} initiated`)
      onSuccess?.(payment.id)
      handleClose()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Refund failed — try again')
    } finally {
      setIsSubmitting(false)
    }
  }

  if (!payment) return null

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[480px]">
        <DialogHeader>
          <DialogTitle className="text-base font-semibold">Refund payment</DialogTitle>
          <DialogDescription className="text-sm text-muted-foreground">
            This will reverse the charge to {payment.client_name}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">

          {/* Amount */}
          <div className="space-y-1.5">
            <label className="text-sm font-medium">Refund amount</label>
            <div className="relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
              <Input
                value={refundAmount}
                onChange={e => setRefundAmount(e.target.value)}
                className="pl-6"
                type="number"
                min="0"
                step="0.01"
                max={(amountCents / 100).toFixed(2)}
                placeholder={(amountCents / 100).toFixed(2)}
              />
            </div>
            <p className="text-xs text-muted-foreground">
              Full amount: {formatCurrency(amountCents)}
            </p>
          </div>

          {/* Reason */}
          <div className="space-y-1.5">
            <label className="text-sm font-medium">Reason</label>
            <Select value={reason} onValueChange={v => { if (v) setReason(v) }}>
              <SelectTrigger>
                <SelectValue placeholder="Select reason" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="duplicate">Duplicate charge</SelectItem>
                <SelectItem value="fraudulent">Fraudulent</SelectItem>
                <SelectItem value="requested_by_customer">Requested by client</SelectItem>
                <SelectItem value="other">Other</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Internal note */}
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-muted-foreground">
              Internal note (optional)
            </label>
            <Textarea
              value={note}
              onChange={e => setNote(e.target.value)}
              placeholder="Add context for your records..."
              rows={2}
            />
          </div>

          {/* Restock inventory — tattoo-specific */}
          {payment.booking_id && (
            <div className="flex items-start gap-2.5 rounded-lg bg-muted/50 px-3 py-2.5">
              <Checkbox
                id="restock"
                checked={restock}
                onCheckedChange={checked => setRestock(checked === true)}
                className="mt-0.5"
              />
              <label htmlFor="restock" className="text-sm leading-snug cursor-pointer">
                Restock inventory used in this booking
              </label>
            </div>
          )}

          {/* Commission reversal notice */}
          {isFullRefund && (payment.commission_amount_cents ?? 0) > 0 && (
            <div className="flex items-start gap-2 rounded-lg bg-[var(--color-warning-bg)] px-3 py-2.5">
              <AlertTriangle className="h-4 w-4 text-[var(--color-warning)] mt-0.5 shrink-0" />
              <p className="text-sm text-[var(--color-warning-foreground)]">
                Commission of{' '}
                {formatCurrency(payment.commission_amount_cents ?? 0)}{' '}
                will also be reversed.
              </p>
            </div>
          )}

          {/* Safety gate — type client name for full refunds >$500 */}
          {needsSafetyGate && (
            <div className="space-y-1.5">
              <label className="text-sm font-medium">
                Type client name to confirm:{' '}
                <span className="font-mono text-foreground">
                  &quot;{payment.client_name}&quot;
                </span>
              </label>
              <Input
                value={confirmName}
                onChange={e => setConfirmName(e.target.value)}
                placeholder={payment.client_name}
                autoComplete="off"
              />
            </div>
          )}

        </div>

        <DialogFooter>
          <Button variant="outline" onClick={handleClose} disabled={isSubmitting}>
            Cancel
          </Button>
          <Button
            variant="destructive"
            disabled={isSubmitting || !canConfirm}
            onClick={handleRefund}
          >
            {isSubmitting ? (
              <>
                <Loader2 className="h-3.5 w-3.5 animate-spin mr-1.5" />
                Processing...
              </>
            ) : (
              `Refund ${formatCurrency(refundCents)} to ${
                payment.card_last4 ? `•••• ${payment.card_last4}` : 'account'
              }`
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

