export function PaymentsPageClient() {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()

  const activeView = (searchParams.get('view') ?? 'all') as SavedView
  const [filterSheetOpen, setFilterSheetOpen] = useState(false)
  const [filters, setFilters] = useState<PaymentsFilters>(EMPTY_FILTERS)
  const [page, setPage] = useState(0)
  const PAGE_SIZE = 25

  const [refundPayment, setRefundPayment] = useState<PaymentRefundModalPayment | null>(null)
  const [invoicePaymentId, setInvoicePaymentId] = useState<string | null>(null)
  const [resendPayment, setResendPayment] = useState<{ id: string; email: string; phone: string } | null>(null)

  const [optimisticUpdates, setOptimisticUpdates] = useState<Record<string, PaymentStatus>>({})

  function setView(view: SavedView) {
    const params = new URLSearchParams(searchParams)
    params.set('view', view)
    router.replace(`${pathname}?${params.toString()}`)
    setPage(0)
  }

  const activeFilterCount = [
    filters.statuses.length > 0,
    filters.methods.length > 0,
    filters.minAmount !== '',
    filters.maxAmount !== '',
    filters.dateFrom !== '',
    filters.dateTo !== '',
    filters.artistId !== '',
    filters.clientSearch !== '',
  ].filter(Boolean).length

  function buildQueryString() {
    const p = new URLSearchParams()
    p.set('page', String(page))
    p.set('limit', String(PAGE_SIZE))
    p.set('view', activeView)
    if (filters.statuses.length) p.set('statuses', filters.statuses.join(','))
    if (filters.methods.length) p.set('methods', filters.methods.join(','))
    if (filters.minAmount) p.set('min_amount', filters.minAmount)
    if (filters.maxAmount) p.set('max_amount', filters.maxAmount)
    if (filters.dateFrom) p.set('from', filters.dateFrom)
    if (filters.dateTo) p.set('to', filters.dateTo)
    if (filters.artistId) p.set('artist_id', filters.artistId)
    if (filters.clientSearch) p.set('q', filters.clientSearch)
    return p.toString()
  }

  const { data, isLoading, refetch } = useQuery<PaymentsApiResponse>({
    queryKey: ['payments', activeView, filters, page],
    queryFn: async () => {
      const res = await fetch(`/api/payments?${buildQueryString()}`)
      if (!res.ok) throw new Error('Failed to load payments')
      return res.json() as Promise<PaymentsApiResponse>
    },
    staleTime: 30_000,
  })

  function handleRefundSuccess(paymentId: string) {
    setOptimisticUpdates(prev => ({ ...prev, [paymentId]: 'refunded' }))
    void refetch()
  }

  const columns: ColumnDef<PaymentRow>[] = [
    {
      accessorKey: 'created_at',
      header: 'Date',
      size: 140,
      cell: ({ row }) => (
        <span className="text-sm tabular-nums">
          {format(new Date(row.original.created_at), 'MMM d, yyyy')}
        </span>
      ),
    },
    {
      accessorKey: 'client_name',
      header: 'Client',
      size: 160,
      cell: ({ row }) => (
        <div className="flex items-center gap-1.5 min-w-0">
          <Avatar className="h-5 w-5 shrink-0">
            <AvatarFallback className="text-[10px]">
              {(row.original.client_name ?? 'C').slice(0, 2).toUpperCase()}
            </AvatarFallback>
          </Avatar>
          <span className="text-sm truncate max-w-[120px]">
            {row.original.client_name ?? '—'}
          </span>
        </div>
      ),
    },
    {
      accessorKey: 'artist_name',
      header: 'Artist',
      size: 140,
      cell: ({ row }) => (
        <span className="text-sm text-muted-foreground">
          {row.original.artist_name ?? '—'}
        </span>
      ),
    },
    {
      accessorKey: 'amount_cents',
      header: () => <span className="block text-right">Amount</span>,
      size: 100,
      cell: ({ row }) => (
        <span className="block text-right font-mono tabular-nums font-semibold text-sm">
          {formatCurrency(row.original.amount_cents)}
        </span>
      ),
    },
    {
      accessorKey: 'method',
      header: 'Method',
      size: 80,
      cell: ({ row }) => (
        <span className="text-sm text-muted-foreground">
          {row.original.method === 'card' && row.original.card_last4
            ? `•••• ${row.original.card_last4}`
            : (row.original.method ?? 'Unknown')}
        </span>
      ),
    },
    {
      accessorKey: 'status',
      header: 'Status',
      size: 100,
      cell: ({ row }) => {
        const status = optimisticUpdates[row.original.id] ?? row.original.status
        return <PaymentStatusBadge status={status} />
      },
    },
    {
      id: 'actions',
      header: '',
      size: 40,
      cell: ({ row }) => (
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
