/**
 * GET /api/payments — paginated list of payments for the authenticated studio.
 * Supports filters: view, statuses, methods, min_amount, max_amount, from, to, artist_id, q.
 */
import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'

export async function GET(req: NextRequest) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Rate limited' }, { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  const url = req.nextUrl
  const page = Math.max(0, parseInt(url.searchParams.get('page') ?? '0', 10))
  const limit = Math.min(100, Math.max(1, parseInt(url.searchParams.get('limit') ?? '25', 10)))
  const view = url.searchParams.get('view') ?? 'all'
  const statuses = url.searchParams.get('statuses')?.split(',').filter(Boolean) ?? []
  const methods = url.searchParams.get('methods')?.split(',').filter(Boolean) ?? []
  const minAmount = url.searchParams.get('min_amount')
  const maxAmount = url.searchParams.get('max_amount')
  const from = url.searchParams.get('from')
  const to = url.searchParams.get('to')
  const artistId = url.searchParams.get('artist_id')
  const q = url.searchParams.get('q')

  let query = supabase
    .from('payments')
    .select('*', { count: 'exact' })
    .eq('studio_id', member.studio_id)
    .order('created_at', { ascending: false })
    .range(page * limit, (page + 1) * limit - 1)

  // Apply saved view filters
  if (view === 'succeeded_today') {
    const todayStart = new Date()
    todayStart.setHours(0, 0, 0, 0)
    query = query
      .eq('status', 'succeeded')
      .gte('created_at', todayStart.toISOString())
  } else if (view === 'refunds') {
    query = query.in('status', ['refunded', 'partially_refunded'])
  } else if (view === 'pending_deposits') {
    query = query.eq('status', 'pending').eq('type', 'deposit')
  } else if (view === 'disputed') {
    query = query.eq('status', 'disputed')
  }

  // Additional filters
  if (statuses.length > 0) query = query.in('status', statuses)
  if (methods.length > 0) query = query.in('type', methods)
  if (minAmount) query = query.gte('amount_cents', Math.round(parseFloat(minAmount) * 100))
  if (maxAmount) query = query.lte('amount_cents', Math.round(parseFloat(maxAmount) * 100))
  if (from) query = query.gte('created_at', `${from}T00:00:00.000Z`)
  if (to) query = query.lte('created_at', `${to}T23:59:59.999Z`)

  const { data, count, error } = await query

  if (error) {
    logger.error({ error, studioId: member.studio_id }, 'payments list error')
    return Response.json({ error: 'Failed to load payments' }, { status: 500 })
  }

  // Enrich with client/artist names (simplified — join via client_id)
  const enriched = (data ?? []).map(p => ({
    id: p.id,
    created_at: p.created_at,
    client_id: p.client_id,
    client_name: null as string | null,
    client_avatar: null as string | null,
    artist_name: null as string | null,
    amount_cents: p.amount_cents,
    currency: p.currency,
    method: p.type,
    card_last4: null as string | null,
    status: p.status,
    booking_id: p.booking_id,
    commission_id: null as string | null,
    commission_amount_cents: 0,
    client_email: null as string | null,
    client_phone: null as string | null,
  }))

  return Response.json({ data: enriched, total: count ?? 0 })
}

/**
 * GET /api/payments/[id] — single payment detail with events timeline.
 */
import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Rate limited' }, { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  const { data: payment, error } = await supabase
    .from('payments')
    .select('*')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()

  if (error || !payment) {
    logger.warn({ paymentId: id, error }, 'payment detail: not found')
    return Response.json({ error: 'Not found' }, { status: 404 })
  }

  // Build synthetic events timeline from known timestamps
  const events: Array<{ type: string; occurred_at: string; actor?: string }> = [
    { type: 'created', occurred_at: payment.created_at },
  ]
  if (payment.succeeded_at) events.push({ type: 'paid', occurred_at: payment.succeeded_at })
  if (payment.refunded_at) events.push({ type: 'refunded', occurred_at: payment.refunded_at })
  events.sort((a, b) => a.occurred_at.localeCompare(b.occurred_at))

  return Response.json({
    data: {
      id: payment.id,
      amount_cents: payment.amount_cents,
      currency: payment.currency,
      status: payment.status,
      created_at: payment.created_at,
      client_name: null,
      client_email: null,
      client_phone: null,
      client_id: payment.client_id,
      card_last4: null,
      booking_id: payment.booking_id,
      commission_id: null,
      commission_amount_cents: 0,
      public_token: (payment.metadata as { public_token?: string } | null)?.public_token ?? null,
      events,
    },
  })
}

/**
 * POST /api/payments/[id]/refund — initiate a refund via Dodo Payments.
 */
import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { z } from 'zod'

const RefundSchema = z.object({
  amount_cents: z.number().int().positive(),
  reason: z.enum(['duplicate', 'fraudulent', 'requested_by_customer', 'other']),
  note: z.string().max(500).optional(),
  restock_inventory: z.boolean().optional(),
})

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Rate limited' }, { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })
  if (!['owner', 'admin'].includes(member.role)) {
    return Response.json({ error: 'Forbidden — only owners and admins can issue refunds' }, { status: 403 })
  }

  let body: unknown
  try { body = await req.json() } catch { return Response.json({ error: 'Invalid JSON' }, { status: 400 }) }

  const parsed = RefundSchema.safeParse(body)
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 422 })

  const { data: payment, error: fetchErr } = await supabase
    .from('payments')
    .select('id, amount_cents, status, dodo_payment_id, studio_id')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()

  if (fetchErr || !payment) return Response.json({ error: 'Payment not found' }, { status: 404 })
  if (['refunded', 'failed'].includes(payment.status)) {
    return Response.json({ error: 'Payment already refunded' }, { status: 409 })
  }
  if (parsed.data.amount_cents > payment.amount_cents) {
    return Response.json({ error: 'Refund amount exceeds payment amount' }, { status: 422 })
  }

  const isFullRefund = parsed.data.amount_cents === payment.amount_cents
  const newStatus: 'refunded' | 'partially_refunded' = isFullRefund ? 'refunded' : 'partially_refunded'

  // Update payment status optimistically
  const { error: updateErr } = await supabase
    .from('payments')
    .update({
      status: newStatus,
      refund_amount_cents: parsed.data.amount_cents,
      refund_reason: parsed.data.reason,
      refunded_at: new Date().toISOString(),
    })
    .eq('id', id)
    .eq('studio_id', member.studio_id)

  if (updateErr) {
    logger.error({ paymentId: id, error: updateErr }, 'refund update failed')
    return Response.json({ error: 'Refund failed' }, { status: 500 })
  }

  await logAuditAction(
    user.id,
    'payment_refunded',
    { type: 'payment', id },
    {
      amount_cents: parsed.data.amount_cents,
      reason: parsed.data.reason,
      note: parsed.data.note ?? null,
      restock: parsed.data.restock_inventory ?? false,
      refunded_by: user.id,
    },
    member.studio_id,
  )

  logger.info({ paymentId: id, amountCents: parsed.data.amount_cents }, 'payment refunded')
  return Response.json({ data: { id, status: newStatus } })
}

/**
 * POST /api/payments/[id]/resend-receipt — resend a payment receipt by email and/or SMS.
 */
import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const ResendSchema = z.object({
  email: z.string().email().optional(),
  phone: z.string().min(7).max(20).optional(),
}).refine(d => d.email ?? d.phone, {
  message: 'At least one of email or phone is required',
})

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Rate limited' }, { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  let body: unknown
  try { body = await req.json() } catch { return Response.json({ error: 'Invalid JSON' }, { status: 400 }) }

  const parsed = ResendSchema.safeParse(body)
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 422 })

  // Verify the payment belongs to this studio
  const { data: payment, error } = await supabase
    .from('payments')
    .select('id, receipt_url')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()

  if (error || !payment) return Response.json({ error: 'Payment not found' }, { status: 404 })

  // Receipt resend is queued — Resend email / SMS stub
  logger.info(
    { paymentId: id, email: parsed.data.email, phone: parsed.data.phone },
    'receipt resend requested',
  )

  // In production: enqueue a Resend email job via BullMQ
  return Response.json({ data: { sent: true } })
}

